-- Ready-made yatra packages (Kedarnath, Do Dham, Char Dham). Prices are added in Admin → Packages.
-- ON CONFLICT keeps any edits already made in admin.

INSERT INTO "Package" ("id", "slug", "title", "summary", "durationDays", "durationLabel", "tripType", "audience", "priceBasis", "season", "itinerary", "inclusions", "exclusions", "notes", "imageUrl", "imageAlt", "featured", "status", "sortOrder", "updatedAt")
VALUES ('pkg_kedarnath_yatra_5d', 'kedarnath-yatra-5-days', 'Kedarnath Yatra from Haridwar', 'Road journey to Guptkashi or Sitapur, the Gaurikund trek (or your helicopter slot), hotels near the trek start and an experienced hill driver.', 5, '5 days / 4 nights', 'PILGRIMAGE', 'Pilgrims, families and senior citizens', 'Per person on twin sharing · Budget, Standard or Premium hotels', 'Yatra season — roughly May to October / early November; temple opening dates are announced each year', '[{"day":1,"title":"Haridwar → Guptkashi / Sitapur","detail":"Pickup in Haridwar or Rishikesh, drive via Devprayag and Rudraprayag (about 8–9 hrs). Overnight near the trek start."},{"day":2,"title":"Trek to Kedarnath","detail":"Early drive to Sonprayag, shuttle to Gaurikund and the 16–18 km trek (or your official helicopter slot). Evening aarti, overnight at Kedarnath."},{"day":3,"title":"Darshan → back to Guptkashi","detail":"Morning darshan, trek down to Gaurikund and drive back to Guptkashi or Sitapur."},{"day":4,"title":"Guptkashi → Rishikesh / Haridwar","detail":"Drive back with an optional stop at Dhari Devi temple. Overnight in Rishikesh or Haridwar."},{"day":5,"title":"Buffer day / departure","detail":"Kept free for weather or road delays; otherwise drop at Haridwar, Dehradun Airport or onward to Delhi."}]', '["Hotel stays for 4 nights near the trek start, at Kedarnath and in Rishikesh / Haridwar","Choose Budget, Standard or Premium hotels — your quote lists the hotel at every halt.","Daily breakfast and dinner","SUV or tempo traveller with an experienced hill driver for the full route","Fuel, driver allowance, tolls and parking","Registration guidance, weather and road updates, and an on-trip support number"]', '["Official yatra registration (free, done in the pilgrim''s name on the official portal)","Helicopter tickets (sold only on IRCTC HeliYatra)","Pony, palki, pithoo and porter charges","Lunch, temple offerings and special puja fees","Train / flight tickets to Haridwar"]', '["From Delhi, add one day each way.","Kedarnath stays are basic; Guptkashi and Sitapur have more hotel choice.","Routes can close for weather or landslides — the buffer day keeps your darshan safe."]', '/images/hero/kedarnath-temple.webp', 'Kedarnath temple with pilgrims and snow-covered Himalayan peaks behind it', true, 'PUBLISHED', 5, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "_DestinationToPackage" ("A", "B")
SELECT d."id", p."id" FROM "Destination" d, "Package" p
WHERE d."slug" IN ('haridwar', 'rishikesh') AND p."slug" = 'kedarnath-yatra-5-days'
ON CONFLICT DO NOTHING;

INSERT INTO "Package" ("id", "slug", "title", "summary", "durationDays", "durationLabel", "tripType", "audience", "priceBasis", "season", "itinerary", "inclusions", "exclusions", "notes", "imageUrl", "imageAlt", "featured", "status", "sortOrder", "updatedAt")
VALUES ('pkg_do_dham_6d', 'do-dham-kedarnath-badrinath-6-days', 'Do Dham Yatra — Kedarnath & Badrinath', 'Kedarnath and Badrinath in one trip from Haridwar: hotels at every halt, an SUV or tempo traveller with a hill driver, and Mana village.', 6, '6 days / 5 nights', 'PILGRIMAGE', 'Pilgrims, families and senior citizens', 'Per person on twin sharing · Budget, Standard or Premium hotels', 'Yatra season — roughly May to October / early November; temple opening dates are announced each year', '[{"day":1,"title":"Haridwar → Guptkashi / Sitapur","detail":"Drive via Devprayag and Rudraprayag (about 8–9 hrs). Overnight near the Kedarnath trek start."},{"day":2,"title":"Trek to Kedarnath","detail":"Sonprayag → Gaurikund → 16–18 km trek (or helicopter). Evening aarti, overnight at Kedarnath."},{"day":3,"title":"Darshan → Guptkashi","detail":"Morning darshan, trek down and drive back to Guptkashi."},{"day":4,"title":"Guptkashi → Badrinath","detail":"Drive via Chamoli and Joshimath (about 8–9 hrs). Evening darshan at Badrinath."},{"day":5,"title":"Badrinath & Mana → Rudraprayag","detail":"Morning darshan, Mana village and Vyas Gufa, then drive down to Rudraprayag or Srinagar."},{"day":6,"title":"Rudraprayag → Rishikesh / Haridwar","detail":"Drive back via Devprayag, drop at Haridwar, Rishikesh or Dehradun Airport."}]', '["Hotel stays for 5 nights at Guptkashi, Kedarnath, Badrinath and Rudraprayag","Choose Budget, Standard or Premium hotels — your quote lists the hotel at every halt.","Daily breakfast and dinner","SUV or tempo traveller with an experienced hill driver for the full route","Fuel, driver allowance, tolls and parking","Registration guidance, weather and road updates, and an on-trip support number"]', '["Official yatra registration (free, done in the pilgrim''s name on the official portal)","Helicopter tickets (sold only on IRCTC HeliYatra)","Pony, palki, pithoo and porter charges","Lunch, temple offerings and special puja fees","Train / flight tickets to Haridwar"]', '["From Delhi, add one day each way.","Add a buffer day in the monsoon months (July–August).","Badrinath is reachable by road; Kedarnath needs the trek or a helicopter."]', '/images/hero/kedarnath-temple-spire.webp', 'Spire of the Kedarnath temple against snow peaks and clouds', false, 'PUBLISHED', 6, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;

