INSERT INTO "Package" ("id", "slug", "title", "summary", "durationDays", "durationLabel", "tripType", "audience", "priceBasis", "season", "itinerary", "inclusions", "exclusions", "notes", "imageUrl", "imageAlt", "featured", "status", "sortOrder", "updatedAt")
VALUES ('pkg_char_dham_10d', 'char-dham-yatra-10-days', 'Char Dham Yatra from Haridwar', 'Yamunotri, Gangotri, Kedarnath and Badrinath in 10 days: a realistic road plan, hotels at every halt and an SUV or tempo traveller with a hill driver.', 10, '10 days / 9 nights', 'PILGRIMAGE', 'Pilgrims, families and senior citizens', 'Per person on twin sharing · Budget, Standard or Premium hotels', 'Yatra season — roughly May to October / early November; temple opening dates are announced each year', '[{"day":1,"title":"Haridwar → Barkot","detail":"Drive via Mussoorie or Dehradun (about 6–7 hrs). Overnight at Barkot."},{"day":2,"title":"Yamunotri darshan","detail":"Drive to Janki Chatti, trek to Yamunotri (about 6 km each way; ponies available) and back to Barkot."},{"day":3,"title":"Barkot → Uttarkashi","detail":"Drive to Uttarkashi and visit the Vishwanath temple."},{"day":4,"title":"Gangotri darshan","detail":"Day trip to Gangotri via Harsil, then back to Uttarkashi."},{"day":5,"title":"Uttarkashi → Guptkashi / Sitapur","detail":"Long drive via Tehri and Rudraprayag. Overnight near the Kedarnath trek start."},{"day":6,"title":"Trek to Kedarnath","detail":"Sonprayag → Gaurikund → trek (or helicopter). Overnight at Kedarnath."},{"day":7,"title":"Darshan → Guptkashi","detail":"Morning darshan, trek down and drive back to Guptkashi."},{"day":8,"title":"Guptkashi → Badrinath","detail":"Drive via Joshimath. Evening darshan at Badrinath."},{"day":9,"title":"Badrinath & Mana → Rudraprayag","detail":"Morning darshan, Mana village, then drive down to Rudraprayag or Srinagar."},{"day":10,"title":"Back to Rishikesh / Haridwar","detail":"Drive via Devprayag and drop at Haridwar, Rishikesh or Dehradun Airport."}]', '["Hotel stays for 9 nights at every halt","Choose Budget, Standard or Premium hotels — your quote lists the hotel at every halt.","Daily breakfast and dinner","SUV or tempo traveller with an experienced hill driver for the full route","Fuel, driver allowance, tolls and parking","Registration guidance, weather and road updates, and an on-trip support number"]', '["Official yatra registration (free, done in the pilgrim''s name on the official portal)","Helicopter tickets (sold only on IRCTC HeliYatra)","Pony, palki, pithoo and porter charges","Lunch, temple offerings and special puja fees","Train / flight tickets to Haridwar"]', '["From Delhi, add one day each way; add 1–2 buffer days in the monsoon.","Slower plans with rest days are available for senior citizens.","This is not a government website — registration is done on the official portal."]', '/images/hero/devprayag-confluence.webp', 'Devprayag, where the Bhagirathi and Alaknanda rivers meet to form the Ganga', true, 'PUBLISHED', 7, CURRENT_TIMESTAMP)
ON CONFLICT ("slug") DO NOTHING;

